import React, { type FC } from 'react';
import type { SystemIconType } from '../types';

interface SystemIconProps extends SystemIconType {
  visual: FC<SystemIconType>;
}

const SystemIcon = ({ visual: Icon, size = 'sm', color = 'currentColor' }: SystemIconProps) => (
  <Icon size={size} color={color} />
);

export default SystemIcon;
